/* aesthetic waiting v2.22.0 — generated by scripts/build-registry.mjs. */
@import './aesthetic.base.css';

:root {
  --ae-ink-muted: #737373;
  --ae-line: #e9e9e9;
  --ae-ink-muted-dark: #8f8f8f;
  --ae-line-dark: #262626;
  --ae-w-medium: 550;
  --ae-radius: 0;
  --ae-space-2: 0.5em;
}

@media (prefers-color-scheme: dark) {
  :root:not(.light):not([data-ae-mode='light']) {
    --ae-ink-muted: var(--ae-ink-muted-dark);
    --ae-line: var(--ae-line-dark);
  }
}

.light,
[data-ae-mode='light'] {
  color-scheme: light;
}

:root.dark,
:root[data-ae-mode='dark'] {
  color-scheme: dark;
  --ae-ink-muted: var(--ae-ink-muted-dark);
  --ae-line: var(--ae-line-dark);
}

.ae-chrome {
font-size: 13px;
  color: var(--ae-ink-muted);
}

.ae-chrome a {
color: var(--ae-ink-muted);
  text-decoration: none;
}

.ae-chrome a:hover {
color: var(--ae-ink);
}

.ae-item {
font-weight: var(--ae-w-medium);
}

.ae-dim {
color: var(--ae-ink-muted);
}

.ae-button {
display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--ae-space-2);
  background: var(--ae-ink);
  border: 1px solid var(--ae-ink);
  border-radius: var(--ae-radius);
  color: var(--ae-surface);
  font-weight: var(--ae-w-medium);
  padding: 0.55em 1.5em;
  min-height: 44px;
  cursor: pointer;
  transition:
    opacity var(--ae-quick) var(--ae-ease),
    background-color var(--ae-quick) var(--ae-ease),
    transform var(--ae-quick) var(--ae-ease);
}

.ae-button:hover {
opacity: 0.9;
}

.ae-button:active {
transform: translateY(1px) scale(0.99);
}

.ae-button:disabled {
cursor: default;
  opacity: 0.7;
  transform: none;
}

.ae-button-quiet {
background: transparent;
  color: var(--ae-ink);
}

.ae-button-quiet:hover {
background: var(--ae-wash);
  opacity: 1;
}

.ae-skeleton {
display: block;
  background: var(--ae-wash);
  color: transparent;
  pointer-events: none;
  user-select: none;
}

.ae-skeleton * {
visibility: hidden;
}

.ae-empty {
padding: 2.4em 0;
  border-block: 1px solid var(--ae-line);
}

.ae-empty > p {
margin-bottom: 0.15em;
}

.ae-empty .ae-button {
margin-top: 1.2em;
}
